import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';

// specs/hal-engine-config-hooks/spec.md#11
it('sums reported usage across a missing tool round', async () => {
  const rounds: MessageChunk[][] = [
    [{type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}}, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 2, outputTokens: 3, totalTokens: 5}}],
    [{type: 'tool_use', toolCall: {id: '2', name: 'lookup', input: {}}}, {type: 'stop', stopReason: 'tool_use'}],
    [{type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 7, outputTokens: 11, totalTokens: 18}}],
  ];
  let index = 0;
  const provider: AIProvider = {
    async *sendMessage() { yield* rounds[index++]; },
    async generateStructured<T>() { return {} as T; },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'Look up', inputSchema: {type: 'object'}}, async () => 'found');
  let reported: UsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), registry, {
    hooks: {afterModelResponse: async (_session, _text, usage) => { reported = usage; }},
  });
  await orchestrator.processMessage({sessionId: '1', userId: '1', entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}]});
  expect(reported).toEqual({inputTokens: 9, outputTokens: 14, totalTokens: 23});
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/usageTotals.test.ts"
